int replace_net_table(struct net *net, const void __user *user, unsigned int len)
{
    struct tmp_table_info *tmp;
    int num_entries, ret = 0;
    size_t alloc_size;

    if (len < sizeof(struct tmp_table_info))
        return -EINVAL;

    num_entries = len / sizeof(struct table_entry);
    if (len != num_entries * sizeof(struct table_entry))
        return -EINVAL;

    if (num_entries < 0)
        return -EOVERFLOW;

    alloc_size = sizeof(struct tmp_table_info) + (num_entries * sizeof(struct table_entry));
    if (alloc_size < len)
        return -EOVERFLOW;

    tmp = kmalloc(alloc_size, GFP_KERNEL);
    if (!tmp)
        return -ENOMEM;

    if (copy_from_user(tmp, user, len)) {
        kfree(tmp);
        return -EFAULT;
    }

    ret = validate_table_info(tmp, num_entries);
    if (ret) {
        kfree(tmp);
        return ret;
    }

    ret = finalize_table_replacement(net, tmp);
    if (ret) {
        kfree(tmp);
        return ret;
    }

    return 0;
}

