{
    struct new_table_info *temp_table;
    int num_entries;
    int ret = 0;

    if (len % sizeof(struct table_entry) != 0) {
        return -EINVAL;
    }

    num_entries = len / sizeof(struct table_entry);

    if (num_entries <= 0 || num_entries > MAX_TABLE_ENTRIES) {
        return -ERANGE;
    }

    temp_table = kmalloc(len, GFP_KERNEL);
    if (!temp_table) {
        return -ENOMEM;
    }

    if (copy_from_user(temp_table, user, len)) {
        ret = -EFAULT;
        goto free_temp_table;
    }

    ret = finalize_table_replacement(net, temp_table, num_entries);
    if (ret < 0) {
        goto free_temp_table;
    }

    return 0;

free_temp_table:
    kfree(temp_table);
    return ret;
}

